import type { McqBank } from "./types";
import { mcq } from "./build";

/**
 * REG question bank, sixth batch (November 2026): six more questions per topic, on concepts
 * the earlier batches do not cover. Rules changed by the 2025 tax law are avoided.
 */
export const regBankF: McqBank = {
  "circular-230-and-practitioner-ethics": [
    mcq("Under Circular 230, a CPA who is not an attorney may represent clients before the IRS but may not:", [["Prepare returns", "CPAs may prepare returns."], ["Engage in the unauthorized practice of law", "Correct — §10.32."], ["Charge fees", "Fees are allowed."], ["Communicate with the IRS", "Representation involves communication."]], 1, "Section 10.32 says Circular 230 does not authorize the practice of law; practitioners must not give legal services they are not licensed to provide.", "EASY", "CONCEPTUAL", ["practice of law"]),
    mcq("A former IRS employee who personally worked on a taxpayer's case leaves to join a CPA firm. Under Circular 230 §10.25, the former employee:", [["May immediately represent the taxpayer in that matter", "Restrictions apply."], ["May not represent anyone in that particular matter in which they participated personally and substantially", "Correct."], ["Is barred from all practice for life", "Too broad."], ["Must notify the taxpayer only", "The restriction is substantive."]], 1, "Former government employees face restrictions on representing others in matters they worked on, to prevent conflicts and misuse of inside information.", "MEDIUM", "CONCEPTUAL", ["former government employees"]),
    mcq("Under Circular 230 §10.51, which is an example of disreputable conduct?", [["Charging a reasonable hourly fee", "Permitted."], ["Knowingly giving false or misleading information to the IRS", "Correct."], ["Advising a client to take a position with substantial authority", "Permitted."], ["Requesting an extension", "Permitted."]], 1, "Incompetence and disreputable conduct include false statements to the IRS, conviction of certain crimes and willful failure to file one's own returns.", "EASY", "CONCEPTUAL", ["sanctions"]),
    mcq("An enrolled agent renews enrolment every three years. The continuing education requirement is generally:", [["None", "CE is required."], ["72 hours over the three-year cycle, with at least 16 hours a year including 2 hours of ethics", "Correct."], ["120 hours a year", "Too high."], ["24 hours over three years", "Too low."]], 1, "Enrolled agents must complete 72 hours of continuing education per enrollment cycle, with annual minimums and ethics hours.", "MEDIUM", "CONCEPTUAL", ["enrolled agents"]),
    mcq("To become an enrolled agent by examination, a candidate must pass the:", [["Uniform CPA Exam", "That leads to a CPA licence."], ["Special Enrollment Examination (SEE), covering individuals, businesses and representation", "Correct."], ["Bar exam", "That is for attorneys."], ["Annual Filing Season Program test", "That is a voluntary programme for unenrolled preparers."]], 1, "The three-part SEE tests individual taxation, business taxation and representation, practices and procedures; former IRS employees may qualify by experience.", "EASY", "CONCEPTUAL", ["enrolled agents"]),
    mcq("Under Circular 230 §10.82, the IRS may use an expedited suspension procedure against a practitioner who, for example:", [["Charges high fees", "Not a ground."], ["Has had a professional licence revoked or has been convicted of certain crimes", "Correct."], ["Represents many clients", "Not a ground."], ["Uses tax software", "Not a ground."]], 1, "Expedited suspension applies in clear cases such as licence revocation, certain convictions or repeated failure to file returns.", "HARD", "CONCEPTUAL", ["sanctions"]),
  ],

  "irs-procedures-and-appeals": [
    mcq("A taxpayer wants the IRS to abate a penalty assessed on a non-income tax return. The general form for claims for refund and requests for abatement is:", [["Form 1040-X", "That amends an income tax return."], ["Form 843", "Correct."], ["Form 4868", "That extends filing."], ["Form 872", "That extends the statute."]], 1, "Form 843 is used to claim refunds or request abatements of certain taxes, interest and penalties.", "EASY", "CONCEPTUAL", ["forms"]),
    mcq("A taxpayer suffering significant hardship because of an unresolved IRS problem can seek help from:", [["The IRS Criminal Investigation division", "Not its role."], ["The Taxpayer Advocate Service", "Correct."], ["The Tax Court only", "Not the first step."], ["The Office of Professional Responsibility", "That oversees practitioners."]], 1, "The Taxpayer Advocate Service is an independent office within the IRS that helps taxpayers resolve problems and can issue Taxpayer Assistance Orders.", "EASY", "CONCEPTUAL", ["Taxpayer Advocate"]),
    mcq("In a court proceeding, the burden of proof on a factual issue may shift to the IRS if the taxpayer:", [["Simply denies the deficiency", "Not enough."], ["Introduces credible evidence, has kept required records and cooperated with reasonable IRS requests", "Correct."], ["Hires a CPA", "Not the test."], ["Pays the tax", "Not the test."]], 1, "Section 7491 shifts the burden on factual issues if the taxpayer meets the credible evidence, substantiation and cooperation requirements.", "HARD", "CONCEPTUAL", ["burden of proof"]),
    mcq("The IRS believes collection of a tax is in danger because the taxpayer is moving assets abroad. It may make a:", [["Standard assessment after the 90-day letter", "Too slow."], ["Jeopardy assessment, assessing and collecting immediately", "Correct."], ["Private letter ruling", "Not relevant."], ["Offer in compromise", "Not relevant."]], 1, "Jeopardy assessments bypass normal deficiency procedures when collection is at risk, subject to later review.", "MEDIUM", "CONCEPTUAL", ["assessments"]),
    mcq("To request an Appeals conference after an examination when the total proposed change exceeds $25,000 for any period, the taxpayer generally must submit:", [["Nothing", "A protest is required."], ["A formal written protest", "Correct."], ["A Tax Court petition", "That is litigation."], ["Form 4868", "Not relevant."]], 1, "Larger disputes require a formal written protest setting out facts, law and arguments; smaller ones can use a small case request.", "MEDIUM", "CONCEPTUAL", ["appeals"]),
    mcq("The IRS finds an arithmetic error on a return and assesses the extra tax without a notice of deficiency. This is allowed because:", [["The IRS can always assess without notice", "Not true."], ["Mathematical and clerical errors can be corrected by summary assessment", "Correct."], ["The taxpayer agreed", "Not the reason."], ["The amount is small", "Not the test."]], 1, "Math error notices allow summary assessment; the taxpayer can request abatement within 60 days, after which normal deficiency procedures apply.", "MEDIUM", "CONCEPTUAL", ["assessments"]),
  ],

  "business-law-contracts": [
    mcq("A company offers $500 to anyone who finds its lost dog. A person who returns the dog has accepted by:", [["Promising to search", "This is a unilateral contract."], ["Performing the requested act", "Correct."], ["Signing a contract", "Not required."], ["Notifying the company first", "Performance is acceptance."]], 1, "Unilateral contracts are accepted by complete performance; bilateral contracts by a return promise.", "EASY", "APPLICATION", ["acceptance"]),
    mcq("A seller writes, 'If I don't hear from you by Friday, I'll assume you accept.' The buyer says nothing. Generally:", [["A contract is formed", "Silence is not usually acceptance."], ["No contract is formed, because silence is generally not acceptance", "Correct."], ["The buyer must pay", "No contract exists."], ["The seller may sue for breach", "No contract exists."]], 1, "Silence is acceptance only in limited cases, such as prior dealings or where the offeree takes the benefit of services knowing they are offered for payment.", "EASY", "APPLICATION", ["acceptance"]),
    mcq("A buyer promises to buy 'as many widgets as I may choose to order'. This promise is:", [["Enforceable as a requirements contract", "A requirements contract depends on actual needs."], ["Illusory, because the buyer has not committed to anything", "Correct."], ["A firm offer", "Not applicable."], ["Valid under the statute of frauds", "Not the issue."]], 1, "An illusory promise leaves performance entirely to the promisor's discretion, so it is not consideration.", "MEDIUM", "CONCEPTUAL", ["consideration"]),
    mcq("A party signs a contract because the other party threatens physical harm. The contract is:", [["Valid", "Duress makes it voidable."], ["Voidable by the threatened party because of duress", "Correct."], ["Enforceable by both parties", "Not by the wrongdoer against the victim."], ["Void for illegality", "Duress usually makes it voidable."]], 1, "Duress, such as threats of violence or improper economic threats, makes a contract voidable by the victim.", "EASY", "CONCEPTUAL", ["defences"]),
    mcq("A debtor disputes a $1,000 bill in good faith and sends a $700 check marked 'payment in full', which the creditor cashes. This is:", [["Partial payment only", "An accord and satisfaction occurs."], ["An accord and satisfaction, discharging the debt", "Correct."], ["Fraud", "Not fraud."], ["Void", "Not void."]], 1, "When the debt is genuinely disputed, accepting a lesser amount tendered as full payment discharges it.", "MEDIUM", "APPLICATION", ["accord and satisfaction"]),
    mcq("Under the UCC, a merchant seller sells goods to a buyer who picks them up at the seller's store, with no carrier involved. Risk of loss passes to the buyer when:", [["The contract is signed", "Not for a merchant seller."], ["The buyer receives the goods", "Correct."], ["The buyer pays", "Payment is not the test."], ["The goods are identified", "Not the rule."]], 1, "If the seller is a merchant and no carrier is used, risk passes on the buyer's receipt; for non-merchants, on tender of delivery.", "MEDIUM", "APPLICATION", ["risk of loss"]),
  ],

  "business-law-agency-and-business-structures": [
    mcq("A store manager orders inventory and hires staff without explicit instructions, because these are reasonably necessary to run the store. This is:", [["Apparent authority", "That depends on the principal's conduct towards third parties."], ["Implied actual authority", "Correct."], ["No authority", "The acts are within the role."], ["Ratification", "No later approval was needed."]], 1, "Implied authority covers acts reasonably necessary to carry out express authority, based on the position and customs.", "EASY", "APPLICATION", ["authority"]),
    mcq("An agent pays travel costs while carrying out the principal's instructions. The principal generally owes the agent:", [["Nothing", "Principals owe duties to agents."], ["Reimbursement of authorized expenses and indemnification for losses within the agency", "Correct."], ["A share of profits", "Not required."], ["Only compensation, not expenses", "Expenses are reimbursed."]], 1, "Principals owe agents duties of compensation, reimbursement, indemnification and cooperation.", "EASY", "CONCEPTUAL", ["principal's duties"]),
    mcq("A person who is not a partner lets a lender believe he is a partner, and the lender relies on that when lending. The person may be liable as a:", [["Limited partner", "Not the doctrine."], ["Partner by estoppel", "Correct."], ["Silent partner", "That is a real partner."], ["Agent", "Not the doctrine."]], 1, "Partnership by estoppel makes a person liable to third parties who reasonably relied on representations that he was a partner.", "MEDIUM", "CONCEPTUAL", ["partnerships"]),
    mcq("A partner in a limited liability partnership (LLP) is generally NOT personally liable for:", [["Her own malpractice", "Partners remain liable for their own wrongs."], ["Another partner's malpractice in which she was not involved", "Correct."], ["Debts she personally guaranteed", "Guarantees create liability."], ["Her capital contribution", "Her investment is at risk."]], 1, "LLP status shields partners from personal liability for other partners' misconduct and, in most states, for partnership obligations.", "MEDIUM", "CONCEPTUAL", ["LLPs"]),
    mcq("Cumulative voting for directors helps:", [["The majority shareholder control all seats", "It does the opposite."], ["Minority shareholders win representation on the board", "Correct."], ["Directors avoid elections", "Not related."], ["The corporation avoid taxes", "Not related."]], 1, "Shareholders multiply their votes by the number of seats and may concentrate them on one candidate, improving minority representation.", "MEDIUM", "CONCEPTUAL", ["shareholder rights"]),
    mcq("Directors approve a transaction relying in good faith on a report from the company's auditors. If the report proves wrong, the directors are generally:", [["Personally liable", "Good-faith reliance protects them."], ["Protected, because directors may rely on reports of officers and experts they reasonably believe competent", "Correct."], ["Removed automatically", "Not the rule."], ["Liable for fraud", "No fraud is shown."]], 1, "Directors may rely in good faith on information, opinions and reports from officers, employees and professionals.", "EASY", "CONCEPTUAL", ["directors' duties"]),
  ],

  "debtor-creditor-and-bankruptcy": [
    mcq("To file a voluntary Chapter 7 petition, a debtor:", [["Must be insolvent", "Insolvency is not required for voluntary filing."], ["Need not prove insolvency", "Correct."], ["Must have 12 creditors", "That relates to involuntary petitions."], ["Must have creditor approval", "Not required."]], 1, "Voluntary debtors need not be insolvent, though individual consumer debtors must pass the means test and get credit counselling.", "MEDIUM", "CONCEPTUAL", ["Chapter 7"]),
    mcq("A creditor failed to perfect its security interest before the debtor filed for bankruptcy. The trustee can generally:", [["Not affect the security interest", "The trustee can avoid it."], ["Avoid the unperfected security interest, making the creditor unsecured", "Correct."], ["Pay the creditor first", "Not as secured."], ["Convert the debt to equity", "Not the power."]], 1, "The trustee has the rights of a hypothetical lien creditor (the 'strong-arm' power) and can defeat unperfected security interests.", "HARD", "APPLICATION", ["trustee powers"]),
    mcq("In Chapter 11, the court can confirm a plan over a dissenting class of creditors if the plan is fair and equitable and does not discriminate unfairly. This is a:", [["Liquidation", "Not this."], ["Cramdown", "Correct."], ["Reaffirmation", "Not this."], ["Preference", "Not this."]], 1, "Cramdown lets a plan be confirmed despite a dissenting impaired class, if at least one impaired class accepts and the plan meets fairness tests.", "HARD", "CONCEPTUAL", ["Chapter 11"]),
    mcq("A financing statement filed under UCC Article 9 is generally effective for:", [["One year", "The period is longer."], ["Five years, unless a continuation statement is filed", "Correct."], ["Indefinitely", "It lapses without continuation."], ["Until the loan is paid, automatically", "It lapses after five years."]], 1, "Financing statements lapse after five years unless continued within six months before lapse.", "MEDIUM", "CONCEPTUAL", ["perfection"]),
    mcq("A surety pays the creditor in full after the principal debtor defaults. The surety can then step into the creditor's rights against the debtor. This right is:", [["Contribution", "That is between co-sureties."], ["Subrogation", "Correct."], ["Exoneration", "That is to compel the debtor to pay before default."], ["Setoff", "Not this."]], 1, "After paying, a surety gains the creditor's rights, including any collateral, through subrogation, and may also seek reimbursement.", "MEDIUM", "CONCEPTUAL", ["suretyship"]),
    mcq("Two co-sureties guarantee a $100,000 debt, one for $60,000 and the other for $40,000. The first pays the full $100,000 on default. It can recover from the second:", [["$50,000", "Contribution is proportional to amounts guaranteed."], ["$40,000", "Correct — 40% of the loss."], ["$100,000", "Not the rule."], ["$0", "Contribution applies."]], 1, "Co-sureties share losses in proportion to the amounts each guaranteed: $100,000 × $40,000 / $100,000 = $40,000.", "MEDIUM", "CALCULATION", ["suretyship"]),
  ],

  "federal-tax-procedures-and-penalties": [
    mcq("A taxpayer claims property is worth four times its correct value, causing an underpayment. The accuracy-related penalty rate for this gross valuation misstatement is:", [["20%", "That is the standard rate."], ["40%", "Correct."], ["75%", "That is fraud."], ["10%", "Not the rate."]], 1, "Gross valuation misstatements (generally 200% or more of the correct value) double the accuracy-related penalty to 40%.", "HARD", "CONCEPTUAL", ["accuracy-related penalty"]),
    mcq("An employer deposits withheld payroll taxes late. It faces:", [["No penalty if the return is filed on time", "Late deposits are penalized separately."], ["A failure-to-deposit penalty that increases with the length of the delay", "Correct."], ["Only interest", "A penalty also applies."], ["Automatic criminal charges", "Not automatic."]], 1, "The failure-to-deposit penalty is tiered (2%, 5%, 10% and 15%) depending on how late the deposit is.", "MEDIUM", "CONCEPTUAL", ["payroll penalties"]),
    mcq("For most criminal tax offences, such as tax evasion, the statute of limitations is generally:", [["Three years", "Criminal tax limitations are longer."], ["Six years", "Correct."], ["Ten years", "Not the general rule."], ["Unlimited", "Not for most offences."]], 1, "Section 6531 sets a six-year statute of limitations for most criminal tax offences, such as evasion and willful failure to file, compared with three years for civil assessment.", "HARD", "CONCEPTUAL", ["criminal tax"]),
    mcq("A taxpayer wants to disclose a position on her return to reduce penalty exposure. She would generally attach:", [["Form 8275 (or Form 8275-R if contrary to regulations)", "Correct."], ["Form 4868", "That extends filing."], ["Form 843", "That claims refunds or abatements."], ["Form 2848", "That authorizes representatives."]], 0, "Adequate disclosure on Form 8275 lets a position with a reasonable basis avoid the substantial understatement penalty.", "MEDIUM", "CONCEPTUAL", ["disclosure"]),
    mcq("A taxpayer participates in a listed tax shelter transaction but fails to disclose it. The likely consequence is:", [["No penalty", "Penalties apply."], ["A penalty for failure to disclose a reportable transaction, plus possible extension of the statute of limitations", "Correct."], ["Automatic audit only", "Penalties apply."], ["Loss of citizenship", "Not related."]], 1, "Section 6707A penalizes failure to disclose reportable and listed transactions, and the assessment period can stay open until disclosure.", "HARD", "CONCEPTUAL", ["reportable transactions"]),
    mcq("If the civil fraud penalty applies to a portion of an underpayment, the accuracy-related penalty on that same portion is:", [["Added on top", "Penalties do not stack."], ["Not imposed, because the penalties do not stack on the same portion", "Correct."], ["Doubled", "Not the rule."], ["Refunded", "Not the rule."]], 1, "The 20% accuracy-related penalty does not apply to any portion of an underpayment on which the 75% fraud penalty is imposed.", "MEDIUM", "CONCEPTUAL", ["penalties"]),
  ],

  "property-transactions-basis-and-cost-recovery": [
    mcq("Under MACRS, computers, cars and light trucks are generally:", [["3-year property", "Not these items."], ["5-year property", "Correct."], ["7-year property", "That covers office furniture."], ["15-year property", "That covers land improvements."]], 1, "Common MACRS classes: 5-year (computers, cars), 7-year (furniture, most machinery), 15-year (land improvements).", "EASY", "CONCEPTUAL", ["MACRS"]),
    mcq("Office furniture and fixtures are generally depreciated under MACRS over:", [["5 years", "That is for computers and vehicles."], ["7 years", "Correct."], ["39 years", "That is nonresidential real property."], ["3 years", "Not for furniture."]], 1, "Seven-year property includes office furniture, fixtures and equipment not assigned to another class, using 200% declining balance.", "EASY", "CONCEPTUAL", ["MACRS"]),
    mcq("An oil producer may use percentage depletion. A key feature is that it:", [["Is limited to the property's basis", "That is cost depletion."], ["Can continue even after the property's basis has been fully recovered", "Correct."], ["Is available to all taxpayers without limits", "Limits apply."], ["Is always smaller than cost depletion", "Not necessarily."]], 1, "Percentage depletion is a statutory percentage of gross income from the property, subject to limits, and can exceed basis.", "MEDIUM", "CONCEPTUAL", ["depletion"]),
    mcq("A business building with an adjusted basis of $200,000 is damaged; insurance pays $50,000 and the taxpayer recognizes no gain or loss. The building's basis becomes:", [["$200,000", "Insurance recoveries reduce basis."], ["$150,000", "Correct — basis is reduced by the insurance received."], ["$250,000", "Not the calculation."], ["$50,000", "Not the calculation."]], 1, "Basis is reduced by insurance proceeds and any deductible casualty loss, and increased by later restoration costs.", "MEDIUM", "CALCULATION", ["basis adjustments"]),
    mcq("In a divorce, one spouse transfers stock (basis $30,000, value $80,000) to the other. The recipient's basis is:", [["$80,000", "Transfers between spouses use carryover basis."], ["$30,000", "Correct — Section 1041."], ["$55,000", "Not the calculation."], ["$0", "Not the rule."]], 1, "Transfers between spouses or incident to divorce are tax-free, and the recipient takes the transferor's basis.", "MEDIUM", "APPLICATION", ["basis"]),
    mcq("An individual sells a residential rental building depreciated straight-line under MACRS. Under Section 1250, the amount recaptured as ordinary income is generally:", [["All depreciation", "Straight-line depreciation is not ordinary recapture for individuals."], ["None, though the gain from depreciation is taxed at up to 25% as unrecaptured Section 1250 gain", "Correct."], ["Half the depreciation", "Not the rule."], ["The full gain", "Not the rule."]], 1, "For individuals, straight-line depreciation on real property is not recaptured as ordinary income, but the related gain is taxed at a maximum 25% rate.", "MEDIUM", "CONCEPTUAL", ["recapture"]),
  ],

  "property-transactions-gains-losses-and-like-kind-exchanges": [
    mcq("A taxpayer exchanges like-kind property (basis $100,000, value $150,000) and pays $20,000 cash for property worth $170,000. The taxpayer's recognized gain is:", [["$50,000", "Paying boot does not trigger gain."], ["$0", "Correct."], ["$20,000", "Boot paid is not gain."], ["$70,000", "Not the calculation."]], 1, "Giving boot does not cause gain recognition; the boot paid is added to basis: $100,000 + $20,000 = $120,000.", "MEDIUM", "CALCULATION", ["like-kind exchanges"]),
    mcq("A sole proprietor sells his business, including goodwill he built himself. The gain on the self-created goodwill is generally:", [["Ordinary income", "Self-created goodwill is generally a capital asset."], ["Capital gain", "Correct."], ["Tax-free", "It is taxable."], ["Section 1245 recapture", "No amortization was taken."]], 1, "Self-created goodwill has no basis and is generally a capital asset; purchased goodwill amortized under Section 197 can trigger recapture.", "HARD", "APPLICATION", ["goodwill"]),
    mcq("A taxpayer receives real property in a like-kind exchange. The holding period of the new property:", [["Starts on the exchange date", "It tacks."], ["Includes the holding period of the property given up", "Correct."], ["Is always short-term", "Not the rule."], ["Starts when the property is sold", "Not the rule."]], 1, "Property received in a like-kind exchange takes a tacked holding period when the property given up was a capital or Section 1231 asset.", "EASY", "CONCEPTUAL", ["holding period"]),
    mcq("A business sells a delivery van used for three years at a loss. The loss is:", [["A capital loss limited to $3,000", "Business property is Section 1231."], ["A Section 1231 loss, which is ordinary if net 1231 results are a loss", "Correct."], ["Not deductible", "Business losses are deductible."], ["Short-term", "Held over a year."]], 1, "Depreciable business property held over a year is Section 1231 property; net 1231 losses are ordinary, fully deductible.", "MEDIUM", "APPLICATION", ["Section 1231"]),
    mcq("A songwriter sells the copyright to a song she wrote herself. The gain is:", [["Capital gain", "Self-created copyrights are excluded from capital assets."], ["Ordinary income", "Correct."], ["Section 1231 gain", "Not 1231 property."], ["Excluded", "It is taxable."]], 1, "Copyrights and artistic works created by the taxpayer are not capital assets, so their sale produces ordinary income (with an election for some musical works).", "HARD", "APPLICATION", ["capital assets"]),
    mcq("A married individual filing separately has a large net capital loss. The maximum deduction against ordinary income for the year is:", [["$3,000", "The limit for married filing separately is lower."], ["$1,500", "Correct."], ["$0", "A deduction is allowed."], ["Unlimited", "Limits apply."]], 1, "Net capital losses offset up to $3,000 of ordinary income ($1,500 if married filing separately); the rest carries forward.", "EASY", "CONCEPTUAL", ["capital losses"]),
  ],

  "individual-taxation-gross-income": [
    mcq("State unemployment compensation received by an individual is:", [["Excluded from gross income", "It is taxable federally."], ["Included in gross income", "Correct."], ["Excluded if under $10,000", "No general exclusion."], ["Taxed only by the state", "It is federally taxable."]], 1, "Unemployment compensation is fully includible in federal gross income; recipients can ask for voluntary withholding to avoid a balance due.", "EASY", "CONCEPTUAL", ["inclusions"]),
    mcq("An employee receives workers' compensation benefits for a job-related injury. The benefits are:", [["Fully taxable", "They are excluded."], ["Excluded from gross income", "Correct."], ["Taxable above $5,000", "Not the rule."], ["Subject to self-employment tax", "Not applicable."]], 1, "Workers' compensation for occupational sickness or injury is excluded under Section 104.", "EASY", "CONCEPTUAL", ["exclusions"]),
    mcq("A custodial parent receives $12,000 of child support during the year. For the recipient, it is:", [["Fully taxable", "Child support is not income."], ["Excluded from gross income", "Correct."], ["Taxable only above $5,000", "Not the rule."], ["Deductible by the recipient", "Not applicable."]], 1, "Child support is neither taxable to the recipient nor deductible by the payer, unlike alimony under pre-2019 divorce agreements.", "EASY", "CONCEPTUAL", ["exclusions"]),
    mcq("An employer gives an employee $500 cash as a holiday 'gift'. For the employee, it is:", [["An excluded gift", "Employer payments to employees are generally compensation."], ["Taxable compensation", "Correct."], ["A de minimis fringe", "Cash is never de minimis."], ["Excluded up to $500", "No such rule."]], 1, "Transfers from employers to employees are generally not gifts; cash and cash equivalents are taxable even in small amounts.", "EASY", "APPLICATION", ["compensation"]),
    mcq("Interest on bonds issued by a US state or city for general public purposes is generally:", [["Fully taxable federally", "It is generally excluded."], ["Excluded from federal gross income", "Correct — though private activity bond interest can be an AMT preference."], ["Taxable only for corporations", "Not the rule."], ["Taxed at capital gain rates", "Not the rule."]], 1, "Section 103 excludes interest on most state and local government bonds from federal gross income.", "EASY", "CONCEPTUAL", ["exclusions"]),
    mcq("A mutual fund distributes capital gain dividends to an individual shareholder. They are taxed as:", [["Ordinary income", "Capital gain distributions keep their character."], ["Long-term capital gains, regardless of how long the investor held the fund", "Correct."], ["Short-term gains", "Not the rule."], ["Tax-free", "They are taxable."]], 1, "Capital gain distributions reported by a fund are treated as long-term capital gain to shareholders.", "MEDIUM", "CONCEPTUAL", ["investment income"]),
  ],

  "individual-taxation-adjustments-and-deductions": [
    mcq("Interest on a mortgage secured by a taxpayer's second home (a vacation home not rented out) is:", [["Never deductible", "A second home can qualify."], ["Deductible as qualified residence interest, within the acquisition debt limit", "Correct."], ["Deductible as investment interest", "Not investment property."], ["An adjustment", "It is an itemized deduction."]], 1, "Qualified residence interest covers a principal residence and one other residence, subject to the overall acquisition debt limit.", "MEDIUM", "CONCEPTUAL", ["mortgage interest"]),
    mcq("A CPA volunteers 20 hours of accounting services to a charity, usually worth $150 an hour, and drives 200 miles for it. She may deduct:", [["$3,000 for the services", "The value of services is not deductible."], ["Only the unreimbursed out-of-pocket costs, such as charitable mileage", "Correct."], ["Nothing", "Out-of-pocket costs can be deducted."], ["Both the services and the mileage", "Services are not deductible."]], 1, "The value of contributed services is not deductible, but unreimbursed expenses incurred in rendering them are (if itemizing).", "MEDIUM", "APPLICATION", ["charitable contributions"]),
    mcq("The standard mileage rate for driving in service of a charitable organization is set by statute at:", [["The business mileage rate", "It is lower."], ["14 cents a mile", "Correct."], ["Zero", "It is deductible."], ["The medical mileage rate", "Different rate."]], 1, "The charitable mileage rate is fixed by law at 14 cents a mile and is not adjusted for inflation.", "MEDIUM", "CONCEPTUAL", ["charitable contributions"]),
    mcq("A self-employed person may deduct home office expenses if the space is used:", [["Occasionally for business", "Regular use is required."], ["Regularly and exclusively as the principal place of business (or to meet clients)", "Correct."], ["As a guest room on weekends", "Exclusive use fails."], ["For any purpose", "Not the rule."]], 1, "The home office deduction requires regular and exclusive business use; a simplified method is available.", "EASY", "CONCEPTUAL", ["home office"]),
    mcq("A taxpayer's investment interest expense exceeds her net investment income. To increase the deduction, she can elect to:", [["Deduct it as mortgage interest", "Not allowed."], ["Treat qualified dividends or net capital gains as investment income, giving up the lower tax rate on them", "Correct."], ["Carry it back", "Investment interest carries forward."], ["Deduct it as a business expense", "Not allowed."]], 1, "Electing to include qualified dividends and capital gains in investment income increases the deductible amount, but those items are then taxed at ordinary rates.", "HARD", "CONCEPTUAL", ["investment interest"]),
    mcq("A patient travels to another city for surgery. Lodging costs (not lavish) are deductible as medical expenses up to:", [["The full cost", "A daily limit applies."], ["$50 a night per person", "Correct."], ["$100 a night", "Not the limit."], ["Nothing; lodging is personal", "Some lodging is deductible."]], 1, "Lodging while away from home primarily for medical care at a licensed hospital or equivalent facility is deductible up to $50 per night per person.", "MEDIUM", "CONCEPTUAL", ["medical expenses"]),
  ],

  "filing-status-credits-and-amt": [
    mcq("A taxpayer with no qualifying child may still claim the earned income credit if, among other things, she:", [["Is under 18", "There is a minimum age."], ["Meets the age requirement (generally 25 to 64) and other eligibility rules", "Correct."], ["Has investment income above the limit", "That disqualifies."], ["Files married filing separately in all cases", "Not the test."]], 1, "Childless workers can claim a smaller EITC if they meet age, residency, income and other requirements.", "MEDIUM", "CONCEPTUAL", ["earned income credit"]),
    mcq("To be a qualifying person for the child and dependent care credit, a child generally must be:", [["Under 17", "That is the child tax credit age."], ["Under 13 when the care is provided", "Correct."], ["Under 19", "That is a dependency age test."], ["Any age", "Not the rule, except for incapable dependents."]], 1, "Qualifying persons are dependents under 13, or a spouse or dependent physically or mentally incapable of self-care.", "EASY", "CONCEPTUAL", ["dependent care"]),
    mcq("The foreign tax credit is generally limited to:", [["The foreign tax paid, without limit", "A limit applies."], ["US tax multiplied by the ratio of foreign-source taxable income to worldwide taxable income", "Correct."], ["10% of foreign income", "Not the formula."], ["Zero for individuals", "Individuals can claim it."]], 1, "The limitation prevents foreign taxes from offsetting US tax on US-source income; excess credits can be carried back one year and forward ten.", "MEDIUM", "CONCEPTUAL", ["foreign tax credit"]),
    mcq("For high-income taxpayers, the AMT exemption:", [["Increases with income", "It phases out."], ["Phases out as alternative minimum taxable income exceeds a threshold", "Correct."], ["Is not available", "It is available but reduced."], ["Is the same for everyone", "It phases out."]], 1, "The AMT exemption is reduced as AMTI rises above a threshold, which can increase AMT exposure for higher earners.", "MEDIUM", "CONCEPTUAL", ["AMT"]),
    mcq("A college student is claimed as a dependent by her parents. On her own return, she:", [["May claim her own dependents", "A dependent cannot claim dependents."], ["Cannot claim anyone as a dependent", "Correct."], ["Must file jointly with her parents", "Not possible."], ["Gets a full standard deduction regardless of earnings", "Her standard deduction is limited."]], 1, "A person who is a dependent of another taxpayer cannot claim dependents, and has a limited standard deduction.", "EASY", "CONCEPTUAL", ["dependents"]),
    mcq("Unused general business credits are generally:", [["Lost", "They carry over."], ["Carried back one year and forward 20 years", "Correct."], ["Refunded", "Most are not refundable."], ["Carried forward 5 years only", "The period is longer."]], 1, "The general business credit is limited by tax liability; unused amounts carry back one year and forward 20 years.", "HARD", "CONCEPTUAL", ["business credits"]),
  ],

  "retirement-plans-and-tax-planning-basics": [
    mcq("A 40-year-old withdraws $10,000 from a Roth IRA to which she has contributed $15,000. Earnings are $5,000. The withdrawal is:", [["Taxable and penalized", "Contributions come out first."], ["Tax-free and penalty-free, because contributions are withdrawn first", "Correct."], ["Taxable but not penalized", "Contributions are not taxable."], ["Partly taxable", "Only after contributions are exhausted."]], 1, "Roth IRA ordering rules treat distributions as coming first from contributions, then conversions, then earnings.", "MEDIUM", "APPLICATION", ["Roth IRA"]),
    mcq("A 403(b) plan is generally available to employees of:", [["Any business", "403(b) plans are for specific employers."], ["Public schools and Section 501(c)(3) tax-exempt organizations", "Correct."], ["Only state governments", "Too narrow."], ["Only self-employed people", "Not this plan."]], 1, "403(b) tax-sheltered annuity plans serve employees of public schools and 501(c)(3) organizations, with limits similar to 401(k) plans.", "EASY", "CONCEPTUAL", ["plan types"]),
    mcq("A 50-year-old leaves a state government job and takes a distribution from the governmental 457(b) plan. The 10% additional tax on early distributions:", [["Applies", "It generally does not apply to governmental 457(b) distributions."], ["Generally does not apply (unless the amount came from a rollover from another plan type)", "Correct."], ["Is 25%", "Not the rule."], ["Applies only after 59½", "Not the rule."]], 1, "Governmental 457(b) distributions are taxable but generally exempt from the 10% early distribution tax.", "HARD", "CONCEPTUAL", ["457 plans"]),
    mcq("A 75-year-old employee who owns 2% of her employer and is still working may generally delay RMDs from the employer's 401(k) until:", [["Age 70½", "Not the rule."], ["April 1 after the year she retires", "Correct — the still-working exception."], ["She dies", "Not the rule."], ["She turns 80", "Not the rule."]], 1, "Employees who own 5% or less can delay RMDs from their current employer's plan until retirement; IRAs do not get this exception.", "HARD", "APPLICATION", ["required minimum distributions"]),
    mcq("A 401(k) participant takes a hardship distribution. It is:", [["Tax-free", "Hardship distributions are taxable."], ["Taxable, and may also be subject to the 10% additional tax if under 59½", "Correct."], ["Repaid automatically", "It is not a loan."], ["Allowed for any reason", "A hardship is required."]], 1, "Hardship distributions require an immediate and heavy financial need, are taxable and generally cannot be rolled over.", "MEDIUM", "CONCEPTUAL", ["distributions"]),
    mcq("Under SECURE 2.0, an employer may make 401(k) matching contributions based on an employee's:", [["Credit card payments", "Not eligible."], ["Qualified student loan payments, as if they were elective deferrals", "Correct."], ["Rent payments", "Not eligible."], ["Car loan payments", "Not eligible."]], 1, "Employers may treat qualified student loan payments as elective deferrals for matching purposes, helping employees with debt save for retirement.", "MEDIUM", "CONCEPTUAL", ["SECURE 2.0"]),
  ],

  "c-corporation-taxation": [
    mcq("A corporation has taxable income before the dividends received deduction of $80,000, including $100,000 of dividends from a 30%-owned company (with a $20,000 operating loss). The DRD (65%) is generally limited to:", [["$65,000", "The taxable income limit applies here."], ["$52,000 — 65% of taxable income before the DRD", "Correct, unless taking the full DRD creates an NOL."], ["$80,000", "Not the calculation."], ["$0", "A DRD is allowed."]], 1, "The DRD is limited to the percentage of taxable income (computed without the DRD), unless the full deduction creates or increases an NOL.", "HARD", "CALCULATION", ["dividends received deduction"]),
    mcq("To claim the dividends received deduction, a corporation must generally hold the stock for more than:", [["10 days", "The period is longer."], ["45 days during the required period around the ex-dividend date", "Correct."], ["One year", "Not required."], ["Five years", "Not required."]], 1, "The holding period requirement (more than 45 days within a 91-day window) prevents buying shares just to capture dividends.", "MEDIUM", "CONCEPTUAL", ["dividends received deduction"]),
    mcq("Schedule M-2 of Form 1120 analyses changes in:", [["Taxable income", "That is M-1."], ["Unappropriated retained earnings per books", "Correct."], ["Payroll", "Not relevant."], ["Depreciation", "Not relevant."]], 1, "Schedule M-2 reconciles beginning and ending unappropriated retained earnings, showing net income, dividends and other changes.", "EASY", "CONCEPTUAL", ["Form 1120"]),
    mcq("A corporation issues its own stock for cash or property. The corporation recognizes:", [["Gain equal to the excess over par value", "Not a gain."], ["No gain or loss, under Section 1032", "Correct."], ["Ordinary income", "Not income."], ["A capital gain", "Not a gain."]], 1, "A corporation recognizes no gain or loss on receiving money or property in exchange for its stock.", "EASY", "CONCEPTUAL", ["corporate formation"]),
    mcq("In a Section 351 transfer with no gain recognized, the corporation's basis in the property received is:", [["Fair value", "Carryover basis applies."], ["The transferor's basis, increased by any gain the transferor recognized", "Correct."], ["Zero", "Not the rule."], ["The value of stock issued", "Not the rule."]], 1, "Section 362 gives the corporation a carryover basis (plus gain recognized by the transferor), subject to built-in loss limits.", "MEDIUM", "CONCEPTUAL", ["Section 351"]),
    mcq("A corporation sells property at a loss to its 60% shareholder. The loss is:", [["Fully deductible", "Related-party rules apply."], ["Disallowed under Section 267", "Correct."], ["A capital loss", "It is disallowed."], ["Deferred until year-end", "It is disallowed."]], 1, "Losses on sales between a corporation and a more-than-50% shareholder are disallowed; the buyer may use the loss to reduce later gain.", "MEDIUM", "APPLICATION", ["related parties"]),
  ],

  "s-corporation-taxation": [
    mcq("An S corporation earns tax-exempt interest. For the shareholder, this income:", [["Is taxable", "It keeps its tax-exempt character."], ["Increases stock basis but is recorded in the other adjustments account, not the AAA", "Correct."], ["Reduces basis", "It increases basis."], ["Is ignored", "It increases basis."]], 1, "Tax-exempt income increases shareholder basis so it can be distributed tax-free, but is tracked outside AAA.", "HARD", "CONCEPTUAL", ["AAA"]),
    mcq("May an S corporation own 100% of a C corporation?", [["No", "S corporations may own subsidiaries."], ["Yes, and it may elect to treat a wholly owned corporate subsidiary as a QSub", "Correct."], ["Only up to 50%", "Not the rule."], ["Only if the subsidiary is foreign", "Not the rule."]], 1, "S corporations may own C corporation subsidiaries, and may elect QSub status for 100%-owned domestic subsidiaries.", "MEDIUM", "CONCEPTUAL", ["subsidiaries"]),
    mcq("To be eligible for S status, a corporation must be:", [["Foreign or domestic", "It must be domestic."], ["A domestic corporation that is not an ineligible corporation, such as certain financial institutions or insurance companies", "Correct."], ["Publicly traded", "Not required."], ["At least five years old", "Not required."]], 1, "Eligibility requires a domestic corporation with no more than 100 eligible shareholders and one class of stock, and not an ineligible type.", "EASY", "CONCEPTUAL", ["eligibility"]),
    mcq("A C corporation with an NOL carryforward elects S status. During S years, the NOL:", [["Passes through to shareholders", "C year NOLs do not pass through."], ["Cannot be used, except against built-in gains", "Correct."], ["Is refunded", "Not refunded."], ["Is converted to AAA", "Not the rule."]], 1, "C corporation attributes generally are frozen during S years, though NOL carryforwards can offset built-in gains.", "HARD", "CONCEPTUAL", ["conversions"]),
    mcq("An S corporation's net capital gain is reported to shareholders as:", [["Ordinary business income", "Capital gains are separately stated."], ["A separately stated item that keeps its capital gain character", "Correct."], ["Tax-exempt income", "Not exempt."], ["A corporate-level tax only", "It passes through."]], 1, "Items that may affect shareholders differently, such as capital gains, are separately stated so they keep their character.", "EASY", "CONCEPTUAL", ["separately stated items"]),
    mcq("A shareholder sells all her S corporation shares on March 31. If she and the buyer agree, the corporation can elect to:", [["Ignore the sale", "Allocation is needed."], ["Close its books as of the sale date, allocating items by actual results before and after", "Correct."], ["Allocate all income to the buyer", "Not the rule."], ["Allocate all income to the seller", "Not the rule."]], 1, "Instead of per-share, per-day allocation, an election to terminate the year can allocate items based on actual results when a shareholder's interest ends.", "HARD", "CONCEPTUAL", ["allocations"]),
  ],

  "partnership-taxation": [
    mcq("A new partnership incurs $8,000 of organizational costs. It may deduct in its first year:", [["$8,000", "Only a limited amount is immediately deductible."], ["$5,000, with the rest amortized over 180 months", "Correct."], ["$0", "A deduction is allowed."], ["$4,000", "Not the rule."]], 1, "Partnerships may deduct up to $5,000 of organizational costs (reduced by costs above $50,000) and amortize the rest; syndication costs are not deductible.", "MEDIUM", "CALCULATION", ["organizational costs"]),
    mcq("A partnership pays a partner a fixed 6% return on her capital, regardless of profits. This payment is:", [["A distribution", "It is a guaranteed payment."], ["A guaranteed payment for the use of capital, ordinary income to the partner", "Correct."], ["A capital gain", "Not a gain."], ["Not taxable", "It is taxable."]], 1, "Guaranteed payments can be for services or the use of capital; they are deductible by the partnership (if ordinary) and ordinary income to the partner.", "MEDIUM", "CONCEPTUAL", ["guaranteed payments"]),
    mcq("Why can a partner's capital account differ from her outside basis?", [["They are always equal", "They often differ."], ["Outside basis includes her share of partnership liabilities, and contributed property may be booked at fair value in capital but at tax basis in outside basis", "Correct."], ["Capital accounts include liabilities", "Outside basis includes them."], ["Basis ignores contributions", "Contributions increase basis."]], 1, "Capital accounts track equity (often at book value); outside basis is a tax measure that includes the partner's share of liabilities.", "HARD", "CONCEPTUAL", ["basis"]),
    mcq("A calendar-year partnership files an extension. Its Form 1065 is then due by:", [["April 15", "That is the original individual date."], ["September 15", "Correct — six months after March 15."], ["October 15", "That is the extended individual and C corporation date."], ["December 31", "Not the rule."]], 1, "Partnerships can extend the March 15 due date by six months, to September 15 for calendar-year partnerships.", "EASY", "CONCEPTUAL", ["filing deadlines"]),
    mcq("A partner with an outside basis of $30,000 receives a nonliquidating distribution of $10,000 cash and land with a partnership basis of $25,000. Her basis in the land is:", [["$25,000", "Basis in property is limited to remaining outside basis."], ["$20,000", "Correct — $30,000 − $10,000 cash."], ["$30,000", "Not the rule."], ["$0", "Not the rule."]], 1, "Cash reduces outside basis first; property then takes the lesser of the partnership's basis and the partner's remaining outside basis.", "MEDIUM", "CALCULATION", ["distributions"]),
    mcq("A partnership earns tax-exempt municipal bond interest. A partner's share of it:", [["Is taxable to the partner", "It keeps its exempt character."], ["Is tax-exempt and increases her outside basis", "Correct."], ["Reduces her basis", "It increases basis."], ["Is ignored for basis", "It increases basis."]], 1, "Partners increase basis by their share of tax-exempt income so later distributions of it are not taxed.", "EASY", "CONCEPTUAL", ["basis"]),
  ],

  "trusts-estates-and-gift-tax-basics": [
    mcq("An estate filing Form 1041 may choose:", [["Only a calendar year", "Estates may use a fiscal year."], ["A calendar year or a fiscal year", "Correct."], ["No tax year", "It must choose one."], ["The beneficiary's tax year only", "Not the rule."]], 1, "Estates may adopt a fiscal year, which can defer tax for beneficiaries; most trusts must use a calendar year.", "MEDIUM", "CONCEPTUAL", ["fiduciary returns"]),
    mcq("A complex trust distributes income to beneficiaries within 65 days after year-end. The trustee may elect to:", [["Ignore the distribution", "An election is available."], ["Treat the distribution as made in the prior tax year", "Correct."], ["Deduct it twice", "Not allowed."], ["Pay tax at the beneficiary's rate", "Not the election."]], 1, "The 65-day election lets trustees manage distributable net income and shift income to beneficiaries after seeing year-end results.", "HARD", "CONCEPTUAL", ["trust distributions"]),
    mcq("A person transfers a life insurance policy on his own life to his children and dies two years later. The proceeds are:", [["Excluded from his gross estate", "The three-year rule applies to life insurance."], ["Included in his gross estate under the three-year rule", "Correct."], ["Taxed as income to the children", "Proceeds are excluded from income."], ["Split equally between estate and children", "Not the rule."]], 1, "Section 2035 includes life insurance transferred within three years of death in the gross estate.", "MEDIUM", "APPLICATION", ["gross estate"]),
    mcq("A decedent leaves property in a trust that pays all income to his wife for life, with the remainder to his children. To get a marital deduction, the executor can elect:", [["Gift splitting", "That applies to lifetime gifts."], ["QTIP treatment (qualified terminable interest property)", "Correct."], ["The alternate valuation date", "Not related."], ["Portability", "That is the unused exclusion."]], 1, "A QTIP election allows the marital deduction for a life income interest; the property is then included in the surviving spouse's estate.", "HARD", "CONCEPTUAL", ["marital deduction"]),
    mcq("In a community property state, a husband dies owning community property with his wife. The surviving spouse's half of the property generally:", [["Keeps its old basis", "Community property gets a special rule."], ["Also receives a stepped-up basis to fair value", "Correct — both halves are adjusted."], ["Takes a zero basis", "Not the rule."], ["Is taxed immediately", "Not the rule."]], 1, "Section 1014(b)(6) adjusts the basis of both halves of community property to fair value at the first spouse's death.", "HARD", "CONCEPTUAL", ["basis"]),
    mcq("A simple trust must distribute all its income currently. If the trustee delays paying it out, the beneficiary is taxed on that income:", [["Only when received", "Simple trust income is taxed when required to be distributed."], ["In the year it is required to be distributed, whether or not actually paid", "Correct."], ["Never", "It is taxable."], ["Only if over $600", "Not the rule."]], 1, "Beneficiaries of simple trusts are taxed on income required to be distributed, up to DNI, regardless of actual payment.", "MEDIUM", "CONCEPTUAL", ["trust taxation"]),
  ],

  "employee-benefits-and-payroll-tax": [
    mcq("A family pays a nanny wages above the household employment threshold. The family generally reports and pays the employment taxes on:", [["Form 941", "Household employers usually use Schedule H."], ["Schedule H attached to its Form 1040", "Correct."], ["Form 1099-NEC", "The nanny is an employee."], ["Nothing", "Taxes are due above the threshold."]], 1, "Household employers report Social Security, Medicare and FUTA taxes on Schedule H with their individual returns.", "MEDIUM", "CONCEPTUAL", ["household employees"]),
    mcq("A payee fails to give a payer a correct taxpayer identification number. The payer must generally withhold from reportable payments at:", [["10%", "The rate is higher."], ["24% backup withholding", "Correct."], ["30%", "That applies to some foreign payments."], ["Zero", "Withholding applies."]], 1, "Backup withholding at 24% applies when a payee fails to provide a correct TIN or the IRS notifies the payer.", "MEDIUM", "CONCEPTUAL", ["backup withholding"]),
    mcq("An employer pays a $10,000 bonus separately from regular wages. It may withhold federal income tax using:", [["The flat 22% rate for supplemental wages (below $1 million)", "Correct."], ["Zero", "Withholding applies."], ["The employee's top marginal rate only", "A flat rate is permitted."], ["50%", "Not the rate."]], 0, "Supplemental wages up to $1 million can be withheld at a flat 22%; amounts above $1 million are withheld at 37%.", "MEDIUM", "CONCEPTUAL", ["withholding"]),
    mcq("An employer reimburses employees' business travel under an accountable plan. The reimbursements are:", [["Taxable wages", "Accountable plan reimbursements are excluded."], ["Excluded from wages, if expenses are substantiated and excess amounts returned", "Correct."], ["Deductible by the employee", "They are excluded instead."], ["Subject to FICA", "Not if accountable."]], 1, "Accountable plans require a business connection, substantiation and return of excess; otherwise payments are taxable wages.", "EASY", "CONCEPTUAL", ["reimbursements"]),
    mcq("An employee tells the employer how much income tax to withhold by completing:", [["Form W-2", "That reports wages."], ["Form W-4", "Correct."], ["Form W-9", "That is for TIN certification."], ["Form 941", "That is the employer's return."]], 1, "Form W-4 provides filing status, dependents and adjustments that determine withholding.", "EASY", "CONCEPTUAL", ["withholding"]),
    mcq("Certain workers, such as full-time life insurance agents and some delivery drivers, are 'statutory employees'. For tax purposes they:", [["Are employees for all purposes", "Not exactly."], ["Have FICA withheld but report income and expenses on Schedule C", "Correct."], ["Pay self-employment tax on all income", "FICA is withheld instead."], ["Receive Form 1099 only", "They get Form W-2."]], 1, "Statutory employees receive a W-2 with FICA withheld, but can deduct business expenses on Schedule C.", "HARD", "CONCEPTUAL", ["worker classification"]),
  ],

  "exempt-organizations-basics": [
    mcq("Which exempt organization may file the shorter Form 990-EZ instead of the full Form 990?", [["One with gross receipts under $200,000 and total assets under $500,000", "Correct."], ["Any organization", "Thresholds apply."], ["Only private foundations", "They file Form 990-PF."], ["Only churches", "Churches generally need not file."]], 0, "Form 990-EZ is for smaller organizations; the smallest can file the Form 990-N e-postcard, and private foundations file Form 990-PF.", "MEDIUM", "CONCEPTUAL", ["filing requirements"]),
    mcq("A chamber of commerce that promotes local businesses is most likely exempt under:", [["Section 501(c)(3)", "Business promotion is not a (c)(3) purpose."], ["Section 501(c)(6) as a business league", "Correct."], ["Section 501(c)(7)", "That is for social clubs."], ["Section 527", "That is for political organizations."]], 1, "Business leagues, chambers of commerce and trade associations are exempt under 501(c)(6); dues are deductible as business expenses, not as charitable gifts.", "EASY", "APPLICATION", ["types of exemption"]),
    mcq("Which organization is generally NOT required to file an annual Form 990?", [["A large public charity", "It must file."], ["A church", "Correct."], ["A private foundation", "It files Form 990-PF."], ["A trade association", "It must file."]], 1, "Churches, their integrated auxiliaries and certain other religious organizations are exempt from the annual filing requirement.", "EASY", "CONCEPTUAL", ["filing requirements"]),
    mcq("A professional association earns income from selling advertising in its monthly journal. This income is generally:", [["Excluded as related income", "Advertising is generally unrelated."], ["Unrelated business income", "Correct."], ["A charitable contribution", "Not a gift."], ["Tax-free royalty income", "Not a royalty."]], 1, "Advertising sales in exempt publications are generally unrelated business income, subject to special rules for allocating costs.", "MEDIUM", "APPLICATION", ["UBTI"]),
    mcq("An exempt organization that fails to file its required annual return or notice for three consecutive years:", [["Receives a warning only", "The consequence is automatic."], ["Automatically loses its tax-exempt status", "Correct."], ["Pays a $100 fine", "Not the main consequence."], ["Becomes a private foundation", "Not the consequence."]], 1, "Automatic revocation applies after three consecutive years of not filing; the organization must reapply for exemption.", "MEDIUM", "CONCEPTUAL", ["revocation"]),
    mcq("A private foundation invests heavily in speculative ventures that jeopardise its ability to carry out its exempt purposes. It may face:", [["No consequence", "An excise tax applies."], ["An excise tax on jeopardizing investments", "Correct."], ["UBTI", "Not this rule."], ["Automatic loss of exemption", "Not automatic."]], 1, "Section 4944 imposes excise taxes on private foundations, and managers who knowingly participate, for investments that jeopardize exempt purposes.", "HARD", "CONCEPTUAL", ["private foundations"]),
  ],
};
